int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *m, size_t buf_len, int flags) {
    int copied = 0;
    int err = 0;

    if (!sock || !m || !buf_len)
        return -EINVAL;

    lock_sock(sock);

    while (copied < buf_len) {
        struct sk_buff *skb;
        int skb_len;

        skb = skb_peek(&sock->sk->sk_receive_queue);
        if (!skb) {
            err = wait_for_more_data(sock, flags);
            if (err < 0)
                break;
            continue;
        }

        skb_len = skb->len;
        int bytes_to_copy = min(skb_len, (int)(buf_len - copied));

        err = copy_data_to_msghdr(m, skb->data, bytes_to_copy);
        if (err < 0)
            break;

        copied += bytes_to_copy;
        __skb_pull(skb, bytes_to_copy);

        if (skb->len == 0)
            __skb_unlink(skb, &sock->sk->sk_receive_queue);
    }

    release_sock(sock);

    if (copied > 0)
        return copied;
    else
        return err;
}

int receive_socket_data(struct kiocb *iocb, struct socket *sock, struct msghdr *m, size_t buf_len, int flags) {
    int bytes_copied = 0;
    int result;
    struct sk_buff *skb;

    if (!sock || !m || !buf_len) {
        return -EINVAL;
    }

    lock_sock(sock->sk);

    while (buf_len > 0) {
        skb = skb_peek(&sock->sk->sk_receive_queue);
        if (!skb) {
            result = sock_wait_for_data(sock, flags);
            if (result < 0) {
                bytes_copied = result;
                break;
            }
            continue;
        }

        result = skb_copy_datagram_iovec(skb, 0, m, buf_len);
        if (result < 0) {
            bytes_copied = result;
            break;
        }

        bytes_copied += result;
        buf_len -= result;

        skb_unlink(skb, &sock->sk->sk_receive_queue);
        kfree_skb(skb);
    }

    release_sock(sock->sk);
    return bytes_copied;
}

int receive_socket_data(struct kiocb *iocb, struct socket *sock, struct msghdr *m, size_t buf_len, int flags) {
    int ret = 0;
    struct sock *sk = sock->sk;
    size_t copied = 0;

    if (!sock || !m || !buf_len) {
        return -EINVAL;
    }

    lock_sock(sk);

    while (copied < buf_len) {
        struct sk_buff *skb = skb_peek(&sk->sk_receive_queue);

        if (!skb) {
            if (sk->sk_err || (sk->sk_shutdown & RCV_SHUTDOWN)) {
                if (copied == 0) {
                    ret = -sk->sk_err ? -sk->sk_err : 0;
                }
                break;
            }

            if (flags & MSG_DONTWAIT) {
                ret = -EAGAIN;
                break;
            }

            wait_for_receive(sk);
            continue;
        }

        size_t len = min(skb->len, buf_len - copied);
        ret = skb_copy_datagram_iovec(skb, 0, m->msg_iter.iov, len);

        if (ret < 0) {
            break;
        }

        copied += len;

        if (ret == 0) {
            break;
        }

        skb_pop(&sk->sk_receive_queue);
    }

    release_sock(sk);
    return copied ? copied : ret;
}

int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *m,
                 size_t buf_len, int flags)
{
    int bytes_copied = 0;
    int err = 0;
    size_t remaining = buf_len;

    lock_sock(sock);

    while (remaining > 0) {
        struct sk_buff *skb;
        size_t len;

        skb = skb_dequeue(&sock->sk->sk_receive_queue);
        if (!skb) {
            err = -EAGAIN;
            break;
        }

        len = min(skb->len, remaining);
        err = memcpy_to_msg(m, skb->data, len);
        if (err < 0) {
            kfree_skb(skb);
            break;
        }

        bytes_copied += len;
        remaining -= len;
        m->msg_flags = err;

        kfree_skb(skb);

        if (flags & MSG_WAITALL && bytes_copied < (int)buf_len) {
            release_sock(sock);
            sock->sk->sk_data_ready(sock->sk, 0);
            lock_sock(sock);
        } else {
            break;
        }
    }

    release_sock(sock);

    if (err < 0 && bytes_copied == 0)
        return err;

    return bytes_copied;
}

int receive_socket_data(struct kiocb *iocb, struct socket *sock, struct msghdr *m,
                        size_t buf_len, int flags) {
    struct sock *sk = sock->sk;
    int copied = 0;
    int err = 0;

    if (!sock->file) {
        return -ENOTCONN;
    }

    lock_sock(sk);
    while (copied < (int)buf_len) {
        struct sk_buff *skb;
        const int prev_len = copied;

        skb = skb_peek(&sk->sk_receive_queue);
        if (!skb) {
            err = sock->ops->poll_wait(sock, m->msg_control, flags);
            if (err < 0)
                break;
            if (sk->sk_err || (sk->sk_state == TCP_CLOSE)) {
                err = sk->sk_err ? : -ENOTCONN;
                break;
            }
            if (sk->sk_shutdown & RCV_SHUTDOWN)
                break;
            if (flags & MSG_DONTWAIT) {
                err = -EAGAIN;
                break;
            }
            release_sock(sk);
            schedule();
            lock_sock(sk);
            continue;
        }

        copied = skb->len;
        if (copied > (int)buf_len)
            copied = (int)buf_len;

        err = skb_copy_datagram_iovec(skb, 0, m->msg_iov, copied);
        if (err) {
            break;
        }

        sock_rfree(skb);
        __skb_unlink(skb, &sk->sk_receive_queue);
        kfree_skb(skb);
        break;
    }

    release_sock(sk);
    if (copied > 0 || (copied == 0 && prev_len == 0))
        return copied;
    return err ? err : -ENOMSG;
}
